        _modelPath = Path.Combine(env.ContentRootPath, "Data", "model.zip");
        _logger = logger;
    }

    public void TrainAndEvaluate()
    {
        var mlContext = new MLContext(seed: 42);

        var data = mlContext.Data.LoadFromTextFile<TicketData>(
            _dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        // Capture distinct category labels for confidence mapping
        CategoryLabels = mlContext.Data
            .CreateEnumerable<TicketData>(data, reuseRowObject: false)
            .Select(t => t.Category)
            .Distinct()
            .OrderBy(c => c)
            .ToArray();

        _logger.LogInformation("Loaded {Count} training samples with categories: {Categories}",
            mlContext.Data.CreateEnumerable<TicketData>(data, reuseRowObject: false).Count(),
            string.Join(", ", CategoryLabels));

        var pipeline = mlContext.Transforms.Conversion
                .MapValueToKey("Label", nameof(TicketData.Category))
            .Append(mlContext.Transforms.Text.FeaturizeText("SubjectFeatures", nameof(TicketData.Subject)))
            .Append(mlContext.Transforms.Text.FeaturizeText("DescriptionFeatures", nameof(TicketData.Description)))
            .Append(mlContext.Transforms.Concatenate("Features",
                "SubjectFeatures", "DescriptionFeatures", nameof(TicketData.Priority)))
            .Append(mlContext.Transforms.NormalizeMinMax("Features"))
            .Append(mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy(
                labelColumnName: "Label", featureColumnName: "Features"))
            .Append(mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        // Cross-validate to get metrics (important with small datasets)
        _logger.LogInformation("Running 3-fold cross-validation...");
        var cvResults = mlContext.MulticlassClassification.CrossValidate(data, pipeline, numberOfFolds: 3);

        foreach (var (result, i) in cvResults.Select((r, i) => (r, i)))
        {
            _logger.LogInformation(
                "  Fold {Fold}: MacroAccuracy={MacroAcc:F4}, MicroAccuracy={MicroAcc:F4}, LogLoss={LogLoss:F4}",
                i + 1,
                result.Metrics.MacroAccuracy,
                result.Metrics.MicroAccuracy,
                result.Metrics.LogLoss);
        }

        var avgMacro = cvResults.Average(r => r.Metrics.MacroAccuracy);
        var avgMicro = cvResults.Average(r => r.Metrics.MicroAccuracy);
        var avgLogLoss = cvResults.Average(r => r.Metrics.LogLoss);

        _logger.LogInformation(
            "Cross-validation averages: MacroAccuracy={MacroAcc:F4}, MicroAccuracy={MicroAcc:F4}, LogLoss={LogLoss:F4}",
            avgMacro, avgMicro, avgLogLoss);

        // Train final model on all data
        _logger.LogInformation("Training final model on full dataset...");
        var model = pipeline.Fit(data);

        mlContext.Model.Save(model, data.Schema, _modelPath);
        _logger.LogInformation("Model saved to {Path}", _modelPath);
    }

    public string GetModelPath() => _modelPath;
}

